/**
 * surveys.ts — typed fetch wrapper for the ask-bff survey endpoints.
 *
 * All calls go through the BFF at /api/v1/ask/surveys. The BFF translates
 * these to gRPC calls against ask-svc internally. SurveyService.List (200
 * with real survey rows) and SurveyService.Create (201 with the new Draft,
 * story #1277) are both LIVE. The remaining SurveyService RPCs (update,
 * delete, publish/close/duplicate, etc.) still abort UNIMPLEMENTED
 * server-side per epic #1268, so callers see 501 responses for those until a
 * follow-up story fills them in; that remains expected, tested behavior of
 * this trust boundary.
 *
 * Mirrors frontends/range-mfe/src/api/exercises.ts's envelope helpers
 * (unwrap / parseError / <Vertical>ApiError) so this file doesn't invent a
 * parallel convention.
 */

// Type-only import — erased at build time, so this doesn't create a runtime
// circular dependency with ./questions.ts (which imports parseError/unwrap
// from this file).
import type { WireQuestionType } from "./questions";

/** Survey lifecycle status (proto SurveyStatus, short lowercase form). */
export type SurveyStatus = "unspecified" | "draft" | "published" | "closed";

/** Survey vs. lightweight poll (proto SurveyType, short lowercase form). */
export type SurveyType = "unspecified" | "survey" | "poll";

/**
 * AI-generation lifecycle for a survey created via SurveyService.Generate
 * (story #1278). "" (absent/empty) is a manually created survey (#1277) —
 * a legitimate, permanent state, not a transitional one. "generating" is
 * the async worker's in-flight state; "ready" and "error" are terminal.
 */
export type GenerationStatus = "" | "generating" | "ready" | "error";

/**
 * SurveyDTO — the REST wire shape from ask-bff (services/ask-bff/internal
 * /handlers/survey.go's surveyJSON). Fields with Go's `omitempty` tag are
 * absent from the payload entirely when zero-valued, not just empty
 * strings — modeled here as optional so callers can't assume presence.
 */
export interface SurveyDTO {
  readonly id: string;
  readonly org_id: string;
  readonly title: string;
  readonly description?: string;
  readonly status: SurveyStatus;
  readonly survey_type: SurveyType;
  readonly completion_message?: string;
  readonly question_count: number;
  readonly response_count: number;
  readonly created_by?: string;
  readonly created_at?: string;
  readonly updated_at?: string;
  readonly published_at?: string;
  readonly closed_at?: string;
  readonly deleted_at?: string;
  readonly generation_status?: GenerationStatus;
  readonly generation_error?: string;
  /**
   * Card customization tokens (never hex) — see lib/surveyCardTokens.ts.
   * Optional because a survey written before the columns existed, or by an
   * older service, simply has none; the resolvers fall back to the defaults.
   */
  readonly icon?: string;
  readonly colour?: string;
}

/**
 * StatusCounts — org-wide survey counts by lifecycle status, independent of
 * whatever filter/search is currently applied. Drives the status-tab count
 * pills (SurveyStatusTabs) without a second API call.
 */
export interface StatusCounts {
  readonly total: number;
  readonly draft: number;
  readonly published: number;
  readonly closed: number;
}

/** The all-zero StatusCounts value — shared by the parse fallback below and
 *  by useSurveys's pre-fetch initial state, so there's one canonical "no
 *  data yet" value rather than two independently-maintained literals. */
export const ZERO_STATUS_COUNTS: StatusCounts = {
  total: 0,
  draft: 0,
  published: 0,
  closed: 0,
};

function isFiniteNumber(v: unknown): v is number {
  return typeof v === "number" && Number.isFinite(v);
}

/**
 * parseStatusCounts narrows an `unknown` `status_counts` field to a
 * well-typed StatusCounts, defaulting every stop to 0 when the field is
 * absent or any stop is missing/non-numeric — a malformed count block must
 * never crash the tab pills, only render as zero.
 */
function parseStatusCounts(value: unknown): StatusCounts {
  if (value === null || typeof value !== "object") return ZERO_STATUS_COUNTS;
  const v = value as Record<string, unknown>;
  if (
    !isFiniteNumber(v.total) ||
    !isFiniteNumber(v.draft) ||
    !isFiniteNumber(v.published) ||
    !isFiniteNumber(v.closed)
  ) {
    return ZERO_STATUS_COUNTS;
  }
  return {
    total: v.total,
    draft: v.draft,
    published: v.published,
    closed: v.closed,
  };
}

/** Non-"unspecified" lifecycle values the server accepts as a filter. */
export type FilterableSurveyStatus = "draft" | "published" | "closed";

/** Server-accepted sort keys (ask-bff `GET /api/v1/ask/surveys?sort=`). */
export type SurveySortKey = "created_at" | "status" | "title";

/** Server-accepted sort order (ask-bff `GET /api/v1/ask/surveys?order=`). */
export type SurveySortOrder = "asc" | "desc";

export interface ListSurveysParams {
  readonly status?: FilterableSurveyStatus;
  readonly search?: string;
  readonly sort?: SurveySortKey;
  readonly order?: SurveySortOrder;
}

export interface ListSurveysResponse {
  readonly surveys: readonly SurveyDTO[];
  readonly next_page_token: string;
  readonly status_counts: StatusCounts;
}

export class AskApiError extends Error {
  constructor(
    public readonly status: number,
    message: string,
  ) {
    super(message);
    this.name = "AskApiError";
  }
}

/**
 * parseError reads ask-bff's `{ data: null, error: { code, message } }`
 * error envelope and falls back to `HTTP {status}` when the body isn't JSON
 * or doesn't carry the expected shape.
 */
export async function parseError(r: Response): Promise<AskApiError> {
  let message = `HTTP ${r.status}`;
  try {
    const body = (await r.json()) as { error?: unknown };
    const err = body.error;
    if (
      err !== null &&
      typeof err === "object" &&
      typeof (err as { message?: unknown }).message === "string"
    ) {
      message = (err as { message: string }).message;
    } else if (typeof err === "string") {
      message = err;
    }
  } catch {
    // body is not JSON — keep the default message
  }
  return new AskApiError(r.status, message);
}

/**
 * unwrap — ask-bff wraps every payload in a top-level `{ "data": payload }`
 * envelope (writeJSON). Tolerate both the wrapped shape and a flat shape by
 * returning `body.data` when it's a non-null object, else `body` itself.
 */
export function unwrap(body: unknown): Record<string, unknown> {
  const b = (body ?? {}) as Record<string, unknown>;
  const inner = b.data;
  return (inner !== null && typeof inner === "object" ? inner : b) as Record<
    string,
    unknown
  >;
}

export interface CreateSurveyRequest {
  readonly title: string;
  readonly description?: string;
}

/**
 * createSurvey creates a new survey via SurveyService.Create (story #1277).
 * The RPC is LIVE: ask-svc inserts a Draft (audit-chain + outbox in one tx)
 * and ask-bff returns 201 with the created survey; a non-2xx surfaces as an
 * AskApiError via parseError.
 *
 * Unlike listSurveys's per-survey blanket cast, the two fields this story's
 * caller actually depends on (`id` for the post-create navigation, `title`
 * as basic sanity) are verified present and string-typed before the
 * unwrapped envelope is trusted as a SurveyDTO — a malformed 2xx response
 * throws rather than silently handing back an object with an undefined id,
 * which would otherwise navigate to `/ask/surveys/undefined`.
 */
export async function createSurvey(
  req: CreateSurveyRequest,
): Promise<SurveyDTO> {
  const r = await fetch("/api/v1/ask/surveys", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(req),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string" || typeof data.title !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * buildListSurveysQuery turns a ListSurveysParams into the ask-bff's query
 * string. Absent/empty fields are omitted entirely (an empty search string
 * means "no filter," not "filter on empty title").
 */
function buildListSurveysQuery(params: ListSurveysParams): string {
  const qs = new URLSearchParams();
  if (params.status) qs.set("status", params.status);
  if (params.search && params.search.trim() !== "") qs.set("q", params.search);
  if (params.sort) qs.set("sort", params.sort);
  if (params.order) qs.set("order", params.order);
  return qs.toString();
}

/**
 * listSurveys fetches the surveys visible to the caller's org. The ask-bff
 * does filtering/sorting/searching server-side (`?status=`/`?q=`/`?sort=`/
 * `?order=`) and returns org-wide `status_counts` alongside the (possibly
 * filtered) `surveys` page — callers never filter/sort client-side.
 */
export async function listSurveys(
  params: ListSurveysParams = {},
): Promise<ListSurveysResponse> {
  const query = buildListSurveysQuery(params);
  const url = query
    ? `/api/v1/ask/surveys?${query}`
    : "/api/v1/ask/surveys";
  const r = await fetch(url, { credentials: "include" });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  // proto3 omits empty repeated fields and the Go BFF marshals a nil slice as
  // null, so `surveys` is absent/null for an org with none — normalize to []
  // so every caller can rely on an array.
  const surveys = data.surveys;
  return {
    surveys: Array.isArray(surveys) ? (surveys as readonly SurveyDTO[]) : [],
    next_page_token:
      typeof data.next_page_token === "string" ? data.next_page_token : "",
    status_counts: parseStatusCounts(data.status_counts),
  };
}

