 */
export async function deleteSurvey(id: string, reason?: string): Promise<SurveyDTO> {
  const query =
    reason !== undefined && reason.trim() !== ""
      ? `?${new URLSearchParams({ reason }).toString()}`
      : "";
  const r = await fetch(`/api/v1/ask/surveys/${id}${query}`, {
    method: "DELETE",
    credentials: "include",
  });
