/**
 * branches.ts — the answer-branching REST surface (story #1995).
 *
 * A branch is one conditional route: "when this question is answered with
 * THIS option, go THERE instead of falling through to the next question".
 *
 * READS DO NOT LIVE HERE. Branches ride back inline on every question
 * (`QuestionDTO.branches`, populated by `normalizeQuestion` in
 * `questions.ts`), so there is no `listBranches` — one round-trip loads the
 * editor, and the List and Flow views cannot disagree about which routes
 * exist because there is a single load.
 *
 * Writes are the two colon-actions ask-bff exposes. They are POSTs with the
 * option in the BODY rather than REST sub-resources, because a branch is
 * addressed by (question, ANSWER OPTION) and an option is arbitrary
 * user-authored text that can contain slashes — it cannot be a URL segment.
 */

import { parseError, unwrap } from "./surveys";

/**
 * BranchTargetKind — what a branch's `target.id` names.
 *
 * `"end"` routes to the completion screen and names nothing, so its `id` is
 * always `""`. Readers must take the meaning from `kind` and never from
 * `id`'s presence.
 */
export type BranchTargetKind = "question" | "section" | "end";

/** Where a branch sends the respondent. */
export interface BranchTarget {
  readonly kind: BranchTargetKind;
  /** The target question or section id; `""` when `kind` is `"end"`. */
  readonly id: string;
}

/**
 * BranchDTO — the REST wire shape from ask-bff (`branchJSON` in
 * services/ask-bff/internal/handlers/branch.go).
 *
 * `optionValue` is the branch's anchor: answer options are bare strings in
 * `config.options` with no id, so the option TEXT is the only identity
 * available. A rename would orphan the branch, which is why
 * `updateQuestion` carries an `optionRenames` map that re-anchors it
 * server-side in the same transaction as the config write.
 */
export interface BranchDTO {
  readonly id: string;
  readonly questionId: string;
  readonly optionValue: string;
  readonly target: BranchTarget;
}

/** Narrow an unknown value to a `BranchTargetKind`. */
function isBranchTargetKind(v: unknown): v is BranchTargetKind {
  return v === "question" || v === "section" || v === "end";
}

/**
 * normalizeBranch defends against a malformed row rather than throwing — one
 * bad branch must never fail the whole question list, the same per-field
 * leniency `normalizeQuestion` applies.
 *
 * An unrecognized `kind` degrades to `"end"` rather than to a made-up
 * question id: `"end"` is the one target that is always valid regardless of
 * what else is in the survey, so a corrupt row renders as a harmless
 * route-to-finish instead of a dangling pointer at something that may not
 * exist.
 */
export function normalizeBranch(entry: unknown): BranchDTO {
  const e = (entry ?? {}) as Record<string, unknown>;
  const rawTarget = (e.target ?? {}) as Record<string, unknown>;
  const kind = isBranchTargetKind(rawTarget.kind) ? rawTarget.kind : "end";
  return {
    id: typeof e.id === "string" ? e.id : "",
    questionId: typeof e.questionId === "string" ? e.questionId : "",
    optionValue: typeof e.optionValue === "string" ? e.optionValue : "",
    target: {
      kind,
      // Forced empty for "end" even if the server somehow sent something:
      // the two must never disagree, and `kind` is authoritative.
      id: kind === "end" ? "" : typeof rawTarget.id === "string" ? rawTarget.id : "",
    },
  };
}

/**
 * normalizeBranches maps a raw `branches` array, dropping the whole thing to
 * `[]` when it is absent or not an array. `QuestionDTO.branches` is
 * documented as always-an-array, and this is where that promise is kept.
 */
export function normalizeBranches(raw: unknown): readonly BranchDTO[] {
  if (!Array.isArray(raw)) return [];
  return raw.map(normalizeBranch);
}

/**
 * setBranch creates or replaces the branch on one answer option.
 *
 * An UPSERT keyed on (question, option): configuring a branch and
 * re-pointing an existing one are the same call, so the pill's "click to
 * change it" flow needs no read-modify-write.
 */
export async function setBranch(
  surveyId: string,
  questionId: string,
  optionValue: string,
  target: BranchTarget,
): Promise<BranchDTO> {
  const r = await fetch(
    `/api/v1/ask/surveys/${surveyId}/questions/${questionId}/branches:set`,
    {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ optionValue, target }),
    },
  );
  if (!r.ok) throw await parseError(r);
  return normalizeBranch(unwrap((await r.json()) as unknown));
}

/**
 * removeBranch deletes the branch on one answer option, returning it as it
 * was immediately before removal.
 *
 * Deliberately usable on a question that could no longer ACQUIRE a branch —
 * one retyped by a CSV re-import or AI regeneration — because that is
 * exactly the state an author needs to clean up from.
 */
export async function removeBranch(
  surveyId: string,
  questionId: string,
  optionValue: string,
): Promise<BranchDTO> {
  const r = await fetch(
    `/api/v1/ask/surveys/${surveyId}/questions/${questionId}/branches:remove`,
    {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ optionValue }),
    },
  );
  if (!r.ok) throw await parseError(r);
  return normalizeBranch(unwrap((await r.json()) as unknown));
}


