/**
 * questionConfig.ts — the canonical `ask.questions.config` key names + a set
 * of narrow, total reader helpers (story #1281).
 *
 * `config` is an opaque `google.protobuf.Struct` on the wire and a plain JSON
 * object at the TS boundary — proto3 has no "one of these type-specific
 * shapes" union for JSON-ish blobs. Three sources populate it (the manual
 * survey editor this story builds, the AI-generation stub in
 * `services/ask-svc/src/ask_svc/workers/generation/stub_generator.py`, and
 * eventually an imported survey), and nothing previously enforced a single
 * naming convention between them — see the bug this fixed in
 * `lib/summarizeQuestionConfig.ts`'s doc comment.
 *
 * This module is the TS mirror of `services/ask-svc/src/ask_svc/repo/
 * question_config.py`'s canonical key NAMES (the Python module additionally
 * owns bounded-shape validation server-side; that half has no client-side
 * equivalent here).
 *
 * The reader helpers below are deliberately TOTAL — they never throw. A
 * question's `config` is attacker- and bug-reachable free-form JSON (any
 * producer can write anything under any key), so every read narrows
 * defensively and degrades to `undefined` on a type mismatch rather than
 * crashing the caller (mirrors `api/questions.ts`'s `normalizeQuestion`
 * per-field leniency).
 */

/** Canonical `config` key names shared by every question-config producer/consumer. */
export const QUESTION_CONFIG_KEYS = {
  helpText: "help_text",
  isDemographic: "is_demographic",
  options: "options",
  scaleMin: "scale_min",
  scaleMax: "scale_max",
  scaleMinLabel: "scale_min_label",
  scaleMaxLabel: "scale_max_label",
  matrixRows: "matrix_rows",
  matrixColumns: "matrix_columns",
  matrixAllowMultiple: "matrix_allow_multiple",
  minLength: "min_length",
  maxLength: "max_length",
  placeholder: "placeholder",
  allowDecimals: "allow_decimals",
  numberMin: "number_min",
  numberMax: "number_max",
  dateMin: "date_min",
  dateMax: "date_max",
  dateFormat: "date_format",
} as const;

/** One of `QUESTION_CONFIG_KEYS`' values — the literal wire key strings. */
export type QuestionConfigKey =
  (typeof QUESTION_CONFIG_KEYS)[keyof typeof QUESTION_CONFIG_KEYS];

/**
 * readString narrows `config[key]` to a `string`, else `undefined` — a
 * missing key, a non-string value, or a `null` all degrade the same way.
 */
export function readString(
  config: Record<string, unknown>,
  key: string,
): string | undefined {
  const value = config[key];
  return typeof value === "string" ? value : undefined;
}

/**
 * readNumber narrows `config[key]` to a finite `number`, else `undefined`.
 * `NaN`/`Infinity` are rejected too — a config value that survived JSON
 * round-tripping as one of those is not a usable number for any of this
 * story's numeric fields (scale bounds, length bounds, etc).
 */
export function readNumber(
  config: Record<string, unknown>,
  key: string,
): number | undefined {
  const value = config[key];
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

/** readBoolean narrows `config[key]` to a `boolean`, else `undefined`. */
export function readBoolean(
  config: Record<string, unknown>,
  key: string,
): boolean | undefined {
  const value = config[key];
  return typeof value === "boolean" ? value : undefined;
}

/**
 * readStringArray narrows `config[key]` to a non-empty `readonly string[]`,
 * else `undefined`. `config` is an opaque proto Struct — an array field can
 * carry any JSON value, not just strings (mirrors
 * `summarizeQuestionConfig`'s original "filter out non-string option
 * entries" rationale, now shared here rather than duplicated per caller).
 * Non-string entries are filtered out; if nothing string-shaped survives (or
 * the field isn't an array at all), the result is `undefined` — never an
 * empty array — so callers can chain `?? fallback` cleanly.
 */
export function readStringArray(
  config: Record<string, unknown>,
  key: string,
): readonly string[] | undefined {
  const value = config[key];
  if (!Array.isArray(value)) return undefined;
  const strings = value.filter((entry): entry is string => typeof entry === "string");
  return strings.length > 0 ? strings : undefined;
}


--- frontends/ask-mfe/src/api/questions.ts (336 lines) ---
/**
 * questions.ts — typed fetch wrapper for the ask-bff question routes.
 * GET /api/v1/ask/surveys/{id}/questions (story #1278) backs
 * QuestionsReadOnlyList. Story #1281 (the survey editor's data layer) adds
 * the 5 write calls the QuestionService now exposes: create/get/update/
 * delete a single question, plus a bulk reorder. Reuses surveys.ts's
 * `unwrap`/`parseError`/`AskApiError` envelope helpers rather than
 * reinventing them for a second file.
 */

import { type BranchDTO, normalizeBranches } from "./branches";
import { parseError, unwrap } from "./surveys";

/**
 * QuestionType — proto QUESTION_TYPE_* enum, short lowercase form (mirrors
 * SurveyStatus/SurveyType's convention in surveys.ts). "unspecified" is the
 * defensive fallback for an unexpected/未来 wire value — never crash the
 * question list on it.
 */
export type QuestionType =
  | "unspecified"
  | "single_select"
  | "multiple_select"
  | "rank_order"
  | "free_text"
  | "true_false"
  | "yes_no"
  | "scale"
  | "matrix"
  | "date"
  | "number";

/**
 * WireQuestionType — the 10 canonical, non-"unspecified" QuestionType wire
 * values. `SurveyService.Import`'s `ImportedQuestion.question_type` (story
 * #1279) only ever sends one of these — "unspecified" is a defensive
 * READ-side fallback (see `isQuestionType`'s caller in `listQuestions`) that
 * never makes sense as an outbound value.
 */
export type WireQuestionType = Exclude<QuestionType, "unspecified">;

/**
 * QuestionDTO — the REST wire shape from ask-bff (services/ask-bff/internal
 * /handlers/question.go's questionJSON). No `survey_id` field: the survey id
 * is already the route param the caller supplied, so the BFF never repeats
 * it per-row. `config` is an opaque `google.protobuf.Struct` map — callers
 * narrow it defensively (see lib/summarizeQuestionConfig.ts) rather than
 * trusting specific keys.
 */
export interface QuestionDTO {
  readonly id: string;
  readonly questionType: QuestionType;
  readonly prompt: string;
  readonly position: number;
  readonly required: boolean;
  readonly config: Record<string, unknown>;
  readonly sectionId?: string;
  /**
   * The question's conditional routes, one per branched answer option
   * (story #1995). READ-ONLY: branches are written only by
   * `api/branches.ts`'s `setBranch`/`removeBranch`, never by
   * `updateQuestion`, so an edit-and-save round trip cannot clobber them.
   *
   * Always an array — `[]` for an unbranched question and for every
   * question whose type cannot carry a branch — so callers iterate without
   * a nil check.
   */
  readonly branches: readonly BranchDTO[];
}

export interface ListQuestionsResponse {
  readonly questions: readonly QuestionDTO[];
  readonly next_page_token: string;
}

export interface ListQuestionsOptions {
  readonly pageSize?: number;
  readonly pageToken?: string;
}

/**
 * listQuestions fetches a survey's questions (read-only, story #1278).
 * `config`'s absence/null degrades to `{}` (not every question carries a
 * config, e.g. free_text) rather than surfacing `undefined` to callers.
 */
export async function listQuestions(
  surveyId: string,
  options?: ListQuestionsOptions,
): Promise<ListQuestionsResponse> {
  const params = new URLSearchParams();
  if (options?.pageSize !== undefined) {
    params.set("page_size", String(options.pageSize));
  }
  if (options?.pageToken !== undefined) {
    params.set("page_token", options.pageToken);
  }
  const qs = params.toString();
  const url = `/api/v1/ask/surveys/${surveyId}/questions${qs ? `?${qs}` : ""}`;

  const r = await fetch(url, { credentials: "include" });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);

  const rawQuestions = data.questions;
  const questions: QuestionDTO[] = Array.isArray(rawQuestions)
    ? rawQuestions.map((q) => normalizeQuestion(q))
    : [];

  return {
    questions,
    next_page_token:
      typeof data.next_page_token === "string" ? data.next_page_token : "",
  };
}

/**
 * normalizeQuestion defends against a malformed row rather than throwing —
 * a single bad row must never fail the whole list (mirrors
 * useReferenceDocuments.ts's per-field leniency rationale in studio-mfe).
 * `config` is the one field this story actually renders defensively
 * (summarizeQuestionConfig narrows it further), so an absent/non-object
 * config degrades to `{}` rather than `undefined`.
 *
 * Exported (story #1283, Revision 2) so `sections.ts`'s `reorderSections`
 * can normalize the `question` half of a `sections:reorder` response's
 * mixed-kind `items` array through the SAME leniency, rather than growing a
 * second, drifting copy.
 */
export function normalizeQuestion(entry: unknown): QuestionDTO {
  const e = (entry ?? {}) as Record<string, unknown>;
  const config =
    e.config !== null && typeof e.config === "object"
      ? (e.config as Record<string, unknown>)
      : {};
  return {
    id: typeof e.id === "string" ? e.id : "",
    questionType: isQuestionType(e.questionType) ? e.questionType : "unspecified",
    prompt: typeof e.prompt === "string" ? e.prompt : "",
    position: typeof e.position === "number" ? e.position : 0,
    required: typeof e.required === "boolean" ? e.required : false,
    config,
    // `""` normalises to ABSENT, not to an empty-string section id. ask-bff
    // dropped `omitempty` on this field, so it now ALWAYS emits
    // `"sectionId": ""` for a question in the implicit run (it needs the key
    // present so a GET → mutate → PATCH round trip can express "move this
    // back to the implicit run" via the same `""` clear sentinel
    // `UpdateQuestionRequest` documents). Without this guard every implicit
    // question would arrive carrying a truthy-keyed-but-meaningless
    // `sectionId`, and anything comparing `=== undefined` alone — rather than
    // also checking the id resolves to a real section, which
    // `buildEditorEntries` happens to do — would treat it as sectioned.
    sectionId: typeof e.sectionId === "string" && e.sectionId !== "" ? e.sectionId : undefined,
    // Story #1995. `normalizeBranches` degrades an absent or non-array value
    // to `[]`, which is what makes `QuestionDTO.branches`'s always-an-array
    // promise true even for a response predating this field.
    branches: normalizeBranches(e.branches),
  };
}

/**
 * CreateQuestionRequest — the REST DTO POSTed to
 * `/api/v1/ask/surveys/{surveyId}/questions` (story #1281). Field names are
 * camelCase to match the existing `QuestionDTO`/`questionJSON` convention.
 */
export interface CreateQuestionRequest {
  readonly questionType: QuestionType;
  readonly prompt: string;
  readonly required: boolean;
  readonly config: Record<string, unknown>;
  readonly sectionId?: string;
}

/**
 * UpdateQuestionRequest — the REST DTO PATCHed to
 * `/api/v1/ask/surveys/{surveyId}/questions/{questionId}`. Every field is
 * optional: a PATCH must omit a field entirely to mean "leave unchanged," so
 * an explicit `{ required: false }` and an omitted `required` are different
 * requests the BFF distinguishes. `updateQuestion` relies on
 * `JSON.stringify` dropping `undefined`-valued keys — callers should only
 * set the fields they actually mean to change, never spread a
 * fully-optional object where untouched fields are explicitly `undefined`
 * (that happens to serialize the same way today, but is not the intended
 * shape to rely on).
 *
 * `sectionId`'s clear sentinel (story #1283, plan §3.1) — **`sectionId: ""`
 * is how a caller clears a question's section, never `sectionId: null` and
 * never omitting the field.** Go's `encoding/json` leaves a `*string` field
 * nil for BOTH an absent key and an explicit `null`, so
 * `services/ask-bff/internal/handlers/question.go`'s
 * `updateQuestionRequest.SectionID` cannot distinguish "leave unchanged"
 * from "clear" if either of those encodings is used. Sending `""` allocates
 * the pointer, so the BFF's proto3 `optional string section_id` reports
 * `HasField("section_id") == true` with an empty value, and ask-svc treats
 * present-and-empty as "set NULL" versus present-and-non-empty as "assign."
 * `JSON.stringify` never drops a `""` value (only `undefined` and missing
 * keys are dropped), so this sentinel survives serialization exactly where
 * `null`/omission would not. See `useSectionMutations.ts`'s
 * `assignQuestionToSection` for the one call site that clears a section.
 */
export interface UpdateQuestionRequest {
  readonly questionType?: QuestionType;
  readonly prompt?: string;
  readonly required?: boolean;
  readonly config?: Record<string, unknown>;
  readonly sectionId?: string;
  /**
   * OLD option text -> NEW option text, for the answer options this same
   * request renames (story #1995).
   *
   * Branches are anchored to an option's TEXT, so a rename would orphan
   * them. The server cannot infer the mapping — it sees only the old
   * options list and the new one, and a list where one entry changed is
   * indistinguishable from a delete plus an insert. THIS CLIENT is the only
   * party that knows an edit was a rename, so it states the mapping and
   * ask-svc re-anchors the branches in the same transaction as the config
   * write, BEFORE pruning branches whose option genuinely vanished.
   *
   * Advisory and order-independent: an entry naming an option with no branch
   * is a documented no-op, so over-reporting is safe. Omit it entirely when
   * an edit renames nothing.
   */
  readonly optionRenames?: Readonly<Record<string, string>>;
}

/**
 * createQuestion adds a question to the end of a survey via
 * QuestionService.CreateQuestion (story #1281). 201 on success, response
 * normalized through the same leniency as `listQuestions`'s rows.
 */
export async function createQuestion(
  surveyId: string,
  req: CreateQuestionRequest,
): Promise<QuestionDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/questions`, {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(req),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  return normalizeQuestion(unwrap(body));
}

/** getQuestion fetches a single question by id via QuestionService.GetQuestion. */
export async function getQuestion(
  surveyId: string,
  questionId: string,
): Promise<QuestionDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/questions/${questionId}`, {
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  return normalizeQuestion(unwrap(body));
}

/**
 * updateQuestion patches a single question via QuestionService.UpdateQuestion.
 * `patch` is serialized as-is — only the fields the caller set are present
 * in the request body (see `UpdateQuestionRequest`'s doc comment).
 */
export async function updateQuestion(
  surveyId: string,
  questionId: string,
  patch: UpdateQuestionRequest,
): Promise<QuestionDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/questions/${questionId}`, {
    method: "PATCH",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(patch),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  return normalizeQuestion(unwrap(body));
}

/**
 * deleteQuestion soft-deletes a question via QuestionService.DeleteQuestion.
