/**
 * sections.ts — typed fetch wrapper for the ask-bff Section CRUD routes
 * (story #1283), docs/design/ask-sections.md §4.1:
 * `GET`/`POST /api/v1/ask/surveys/{id}/sections`,
 * `PATCH`/`DELETE /api/v1/ask/surveys/{id}/sections/{sectionId}`.
 *
 * Reuses `questions.ts`/`surveys.ts`'s `unwrap`/`parseError`/`AskApiError`
 * envelope helpers rather than reinventing them for a third file.
 */

import { parseError, unwrap } from "./surveys";
import { normalizeQuestion, type QuestionDTO } from "./questions";

/**
 * SectionSummary — the subset of the wire DTO
 * (services/ask-bff/internal/handlers/section.go's camelCase `sectionJSON`:
 * `id`, `surveyId`, `title`, `description`, `position`, `createdAt`,
 * `updatedAt`) this story's UI needs. `surveyId`/`createdAt`/`updatedAt`
 * are dropped at the normalization boundary — no caller in this story reads
 * them.
 */
export interface SectionSummary {
  readonly id: string;
  readonly title: string;
  readonly description: string;
  readonly position: number;
}

/**
 * normalizeSection defends against a malformed row rather than throwing — a
 * single bad row must never fail the whole list, mirroring
 * `questions.ts`'s `normalizeQuestion`.
 */
function normalizeSection(entry: unknown): SectionSummary {
  const e = (entry ?? {}) as Record<string, unknown>;
  return {
    id: typeof e.id === "string" ? e.id : "",
    title: typeof e.title === "string" ? e.title : "",
    description: typeof e.description === "string" ? e.description : "",
    position: typeof e.position === "number" ? e.position : 0,
  };
}

/**
 * listSections fetches a survey's sections via SectionService.ListSections.
 * `sections`'s absence/null degrades to `[]` rather than surfacing
 * `undefined` to callers, mirroring `listQuestions`.
 */
export async function listSections(surveyId: string): Promise<readonly SectionSummary[]> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/sections`, {
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);

  const rawSections = data.sections;
  return Array.isArray(rawSections) ? rawSections.map((s) => normalizeSection(s)) : [];
}

/**
 * CreateSectionRequest — the REST DTO POSTed to
 * `/api/v1/ask/surveys/{surveyId}/sections`. `description` is genuinely
 * optional (a section can be title-only) — omitted entirely rather than
 * sent as an empty string, matching `JSON.stringify`'s own handling of an
 * absent/`undefined` property.
 */
export interface CreateSectionRequest {
  readonly title: string;
  readonly description?: string;
}

/**
 * UpdateSectionRequest — the REST DTO PATCHed to
 * `/api/v1/ask/surveys/{surveyId}/sections/{sectionId}`. Every field is
 * optional: an omitted field means "leave unchanged" (same partial-update
 * contract as `UpdateQuestionRequest` in `questions.ts`). Unlike a
 * question's `sectionId`, no field here needs the `""`-clears-to-NULL
 * sentinel — a section's own title/description are never cleared to null,
 * only ever replaced with a new (possibly empty) string.
 */
export interface UpdateSectionRequest {
  readonly title?: string;
  readonly description?: string;
}

/**
 * createSection adds a section to a survey via
 * SectionService.CreateSection. 201 on success, response normalized
 * through the same leniency as `listSections`'s rows.
 */
export async function createSection(
  surveyId: string,
  req: CreateSectionRequest,
): Promise<SectionSummary> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/sections`, {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(req),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  return normalizeSection(unwrap(body));
}

/**
 * updateSection patches a single section via SectionService.UpdateSection.
 * `patch` is serialized as-is — only the fields the caller set are present
 * in the request body (see `UpdateSectionRequest`'s doc comment).
 */
export async function updateSection(
  surveyId: string,
  sectionId: string,
  patch: UpdateSectionRequest,
): Promise<SectionSummary> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/sections/${sectionId}`, {
    method: "PATCH",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(patch),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  return normalizeSection(unwrap(body));
}

/**
 * deleteSection soft-deletes a section via SectionService.DeleteSection.
 * Resolves to `undefined` on a 2xx response — the real BFF returns 200
 * with the soft-deleted row (mirroring `DeleteQuestion`'s contract), but no
 * caller in this story needs it back; `useSectionMutations` already holds
 * the local list to update. Deleting a section never deletes its
 * questions — they become unsectioned server-side (Lane A) and the caller
 * refetches/patches its local question list separately.
 */
export async function deleteSection(surveyId: string, sectionId: string): Promise<void> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/sections/${sectionId}`, {
    method: "DELETE",
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
}

/**
 * TopLevelItem — one entry of the request `items` array POSTed to
 * `sections:reorder` (story #1283, docs/design/ask-sections.md §0.2 item 4). A
 * section entry always refers to the WHOLE section (never one of its individual
 * members — those are reordered only by
 * `reorderQuestions`/`assignQuestionToSection`, never by this call).
 *
 * `kind: "question"` remains in the type for wire compatibility — the endpoint
 * still ACCEPTS question refs — but this call is a section-axis-only write, so a
 * question ref conveys nothing about ordering. `surveyDragEngine.resolveDragCommit`
 * is where the payload is built, and its own comment records why sending them
 * was worse than useless.
 */
export interface TopLevelItem {
  readonly kind: "question" | "section";
  readonly id: string;
}

/**
 * TopLevelItemResult — one entry of `reorderSections`'s response `items`
 * array, echoing the new order with the FULL object for each kind (never
 * just the id) so a caller can refresh its local state's fields (e.g. a
 * section's server-recomputed `position`) without a follow-up fetch.
 */
export type TopLevelItemResult =
  | { readonly kind: "question"; readonly question: QuestionDTO }
  | { readonly kind: "section"; readonly section: SectionSummary };

export interface ReorderSectionsResponse {
  readonly items: readonly TopLevelItemResult[];
}

function normalizeTopLevelItemResult(entry: unknown): TopLevelItemResult | null {
  const e = (entry ?? {}) as Record<string, unknown>;
  if (e.kind === "question") {
    return { kind: "question", question: normalizeQuestion(e.question) };
  }
  if (e.kind === "section") {
    return { kind: "section", section: normalizeSection(e.section) };
  }
  return null;
}

/**
 * reorderSections rewrites a survey's SECTION order atomically via
 * `POST /api/v1/ask/surveys/{id}/sections:reorder` (story #1283). It never
 * changes section membership or intra-section order — `questions:reorder` still
 * owns that — it only says which top-level slot each section (as a whole) now
 * occupies. A malformed response row is dropped (same leniency as
 * `listSections`/`listQuestions`) rather than failing the whole call.
 */
export async function reorderSections(
  surveyId: string,
  items: readonly TopLevelItem[],
): Promise<ReorderSectionsResponse> {
  const r = await fetch(`/api/v1/ask/surveys/${surveyId}/sections:reorder`, {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ items }),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);

  const rawItems = data.items;
  const resultItems: TopLevelItemResult[] = Array.isArray(rawItems)
    ? rawItems
        .map((entry) => normalizeTopLevelItemResult(entry))
        .filter((entry): entry is TopLevelItemResult => entry !== null)
    : [];

  return { items: resultItems };
}


