export interface ImportedQuestionInput {
  readonly question_type: WireQuestionType;
  readonly prompt: string;
  readonly required: boolean;
  readonly config: Record<string, unknown>;
}

/**
 * ImportSurveyRequest — the REST DTO POSTed to
 * /api/v1/ask/surveys:import. `survey_type` is omitted (not `undefined`)
