  readonly title: string;
  readonly description?: string;
  readonly survey_type?: SurveyType;
  readonly questions: readonly ImportedQuestionInput[];
}

/**
 * importSurvey creates a new survey with a fully-formed question set in one
 * call via SurveyService.Import (story #1279) — the CSV-import path. The RPC
 * is LIVE: ask-svc inserts the Draft + its questions (audit-chain + outbox in
 * one tx) and ask-bff returns 201 with the created survey; a non-2xx
 * surfaces as an AskApiError via parseError. Mirrors createSurvey's
 * present-and-string-typed `id`/`title` sanity check on the 2xx response —
 * an id-less/title-less 2xx would otherwise navigate to
 * `/ask/surveys/undefined`.
 */
export async function importSurvey(req: ImportSurveyRequest): Promise<SurveyDTO> {
  const r = await fetch("/api/v1/ask/surveys:import", {
    method: "POST",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(req),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string" || typeof data.title !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * getSurvey fetches a single survey by id. Backs both the read-only detail
 * route (routes/SurveyDetailRoute.tsx) and useGenerateSurvey's
 * generating-status poll.
 */
export async function getSurvey(id: string): Promise<SurveyDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${id}`, {
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * deleteSurvey soft-deletes a survey (story #1276 follow-up).
 *
 * `DELETE /api/v1/ask/surveys/{id}` returns **200 with the updated resource**,
 * not 204 — the proto's `DeleteResponse` is non-empty, and the caller needs
 * the row back to confirm `deleted_at` was set. The optional `reason` rides
 * as a query parameter because a DELETE carries no body through the BFF.
 *
 * The survey is soft-deleted, so its questions, sections and responses are
 * retained; nothing here is a hard delete.
 */
export async function deleteSurvey(id: string, reason?: string): Promise<SurveyDTO> {
  const query =
    reason !== undefined && reason.trim() !== ""
      ? `?${new URLSearchParams({ reason }).toString()}`
      : "";
  const r = await fetch(`/api/v1/ask/surveys/${id}${query}`, {
    method: "DELETE",
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * COMPLETION_MESSAGE_MAX_LENGTH — the author-facing cap on a survey's
 * completion message (story #1284). Mirrors ask-svc's
 * `_MAX_COMPLETION_MESSAGE_LEN`, which is the AUTHORITATIVE bound: this
 * constant drives the field's `maxLength` and its character counter, so the
 * two must not drift. The server rejects an over-length value with
 * INVALID_ARGUMENT (surfaced as a 400) regardless of what the client allows.
 */
export const COMPLETION_MESSAGE_MAX_LENGTH = 500;

/**
 * SURVEY_TITLE_MAX_LENGTH / SURVEY_DESCRIPTION_MAX_LENGTH — the other two
 * details-card caps, matching ask-svc's `_MAX_TITLE_LEN` (300) and the 300
 * the create form (`SurveyManualForm`) already applies to a description.
 *
 * The description cap MATCHES ask-svc's `_MAX_DESCRIPTION_LEN` (2000), not the
 * create form's 300. An earlier revision used 300 for surface consistency, and
 * that was wrong: `maxLength` does not TRUNCATE an existing value, so an
 * AI-generated or CSV-imported survey whose description already exceeds 300
 * rendered in full and then refused every keystroke — the author could only
 * delete, with nothing on screen explaining why. The create form's 300 still
 * governs a human typing a NEW description; this is the EDIT surface, and it
 * has to be able to edit whatever the server legitimately stored.
 */
export const SURVEY_TITLE_MAX_LENGTH = 300;
export const SURVEY_DESCRIPTION_MAX_LENGTH = 2000;

/**
 * UpdateSurveyRequest — the PATCH body for `updateSurvey`. Every field is
 * OPTIONAL and omitted-means-unchanged, matching ask-bff's
 * `updateSurveyRequest` pointer fields and ask-svc's `HasField` gating.
 *
 * `completion_message: ""` is a MEANINGFUL value, not an omission: it clears a
 * custom message so respondents see the default again. Callers must therefore
 * build this object by including only the keys they intend to change — never
 * by spreading a full form state, which would silently patch every field.
 */
export interface UpdateSurveyRequest {
  readonly title?: string;
  readonly description?: string;
  readonly survey_type?: Exclude<SurveyType, "unspecified">;
  readonly completion_message?: string;
}

/**
 * updateSurvey patches a survey's author-editable details
 * (`PATCH /api/v1/ask/surveys/{id}`) and returns the updated survey.
 *
 * Validates `id` on the response for the same reason `createSurvey` does — a
 * malformed 2xx must throw rather than hand back an object whose fields the
 * details card would then render as `undefined`.
 */
export async function updateSurvey(
  id: string,
  patch: UpdateSurveyRequest,
): Promise<SurveyDTO> {
  // `encodeURIComponent` on the path segment. Not exploitable today — `id` is a
  // UUID from the caller's own route — but a raw interpolation is the wrong
  // default for a value that reaches a URL, and this is a WRITE. The sibling
  // reads (`getSurvey`, and the question/section fetchers) still interpolate
  // raw; they predate this story and are left alone rather than widened into an
  // unrelated sweep.
  const r = await fetch(`/api/v1/ask/surveys/${encodeURIComponent(id)}`, {
    method: "PATCH",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(patch),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * duplicateSurvey deep-copies a survey into a NEW draft and returns the copy.
 *
 * `POST /api/v1/ask/surveys/{id}:duplicate` — a colon-action, matching
 * `:publish`/`:close`/`:generate`. The returned survey is always a fresh
 * draft with its own id, so the caller must navigate/refetch on `data.id`
 * rather than assuming anything about the source.
 *
 * `title` is verified alongside `id` (as `createSurvey` does) because the
 * success toast names the copy, and an undefined title there would surface
 * as "undefined" to the user.
 */
export async function duplicateSurvey(id: string): Promise<SurveyDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${id}:duplicate`, {
    method: "POST",
    credentials: "include",
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string" || typeof data.title !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * updateSurveyCard changes a survey's card icon and colour.
 *
 * `PATCH /api/v1/ask/surveys/{id}` — the existing Update route, sent with
 * ONLY these two fields. The proto's UpdateRequest makes every field optional,
 * so an omitted title/description is "leave it alone" rather than "clear it";
 * sending the whole survey back would let a stale card overwrite an edit made
 * in the editor meanwhile.
 *
 * Values are TOKEN NAMES (`idea`, `violet`), never hex — see
 * lib/surveyCardTokens.ts for why, and the service validates them.
 */
export async function updateSurveyCard(
  id: string,
  card: { readonly icon: string; readonly colour: string },
): Promise<SurveyDTO> {
  const r = await fetch(`/api/v1/ask/surveys/${id}`, {
    method: "PATCH",
    credentials: "include",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(card),
  });
  if (!r.ok) throw await parseError(r);
  const body = (await r.json()) as unknown;
  const data = unwrap(body);
  if (typeof data.id !== "string") {
    throw new AskApiError(r.status, "Malformed survey response");
  }
  return data as unknown as SurveyDTO;
}

/**
 * updateSurveyDetails renames a survey and/or rewrites its description.
 *
 * Same `PATCH /api/v1/ask/surveys/{id}` route as `updateSurveyCard`, sent with
 * only these two fields so an in-flight card customization cannot be clobbered
 * by a stale icon/colour riding along.
 *
 * `description` is sent even when empty — "" is how the author DELETES a
 * description, and the BFF's `*string` DTO plus the proto's `optional` field
 * carry that distinction all the way to a `COALESCE` that overwrites. Dropping
 * an empty string here (`description || undefined`) would silently make a
 * description impossible to remove once written.
 */
export async function updateSurveyDetails(
  id: string,
  details: { readonly title: string; readonly description: string },
